<?php header('Content-Type: application/json');$d=json_decode(file_get_contents('php://input'),true);$m=strtolower($d['message']??'');$found=[];foreach(($d['products']??[]) as $p){$h=strtolower(($p['name']??'').' '.($p['category']??'').' '.($p['details']??''));foreach(preg_split('/\\s+/',$m) as $w)if(strlen($w)>2&&strpos($h,$w)!==false){$found[]=$p;break;}}$a=$found?'Matching products: '.implode(', ',array_map(fn($x)=>$x['name'].' — ৳'.number_format($x['price']),array_slice($found,0,4))).'. I can compare these for you.':'Tell me your budget and preferred device. I can search products, explain specifications and suggest options.';echo json_encode(['answer'=>$a,'matches'=>$found]);